        trade = []
        if any(sheet.get("index_clause") for sheet in sheets):
            trade.append(
                "The indexed package shares material-price risk; please assess its price and other terms together."
            )
        if any(sheet.get("lead_time_days", 0) > sheets[0].get("lead_time_days", 0) for sheet in sheets):
