                must_haves_ok(case, sheet["terms"], standard_terms(threads[sid]))
                and self.valuation(case, sid, threads[sid], sheet["terms"])[0] <= incumbent_cost * 1.03
                for sheet in latest(threads[sid]).get("term_sheets") or []
